local StateCordonMaker = {}
local PRODUCTS = {
    simple_silk_cordon = { name = "Preprost svileni cordon", silkCost = 2, threadCost = 1, goldCost = 1, time = 4, cost = 80, prestige = 5, happiness = 2, description = "Preprost svileni cordon za slovesnosti." },
    silver_tasseled_cordon = { name = "Srebrnoresasti cordon", silkCost = 2, silverCost = 1, goldCost = 1, threadCost = 1, time = 7, cost = 220, prestige = 12, happiness = 3, description = "Srebrnoresasti cordon za trgovce." },
    gold_woven_cordon = { name = "Zlatopleteni cordon", silkCost = 3, goldCost = 2, silverCost = 1, threadCost = 1, time = 10, cost = 540, prestige = 22, happiness = 4, description = "Zlatopleteni cordon za plemiče." },
    jewel_pinned_cordon = { name = "Draguljnoprity cordon", silkCost = 3, goldCost = 2, silverCost = 1, threadCost = 1, jewelCost = 1, time = 14, cost = 1200, prestige = 35, happiness = 6, description = "Cordon z draguljno priponko za visoke plemiče." },
    pearl_set_cordon = { name = "Bisernavi cordon", silkCost = 3, goldCost = 2, silverCost = 1, threadCost = 1, jewelCost = 1, pearlCost = 1, time = 18, cost = 2600, prestige = 50, happiness = 8, description = "Cordon z biseri za visoko plemstvo." },
    royal_grand_cordon = { name = "Kraljevski veliki cordon", silkCost = 5, goldCost = 3, silverCost = 2, threadCost = 2, jewelCost = 2, pearlCost = 2, time = 25, cost = 5800, prestige = 72, happiness = 13, description = "Veliki kraljevski cordon z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    cordon_workshop = { name = "Cordonska delavnica", cost = { gold = 280, wood = 120, stone = 120, silk = 6, thread = 6 }, upkeep = 6, qualityBonus = 5 },
    ceremonial_loft = { name = "Slovesna podstrešje", cost = { gold = 1000, wood = 280, stone = 240, silver = 6, gold = 4 }, upkeep = 23, qualityBonus = 18 },
    master_cordon_atelier = { name = "Mojstrski cordonski atelje", cost = { gold = 2800, wood = 380, stone = 520, silver = 32, gold = 6 }, upkeep = 65, qualityBonus = 30 },
    royal_ceremony_palace = { name = "Kraljevska slovesna palača", cost = { gold = 12000, wood = 600, stone = 800, gold = 80, jewel = 18 }, upkeep = 240, qualityBonus = 55, prestigeBonus = 50 },
}
StateCordonMaker.silkStock = 14; StateCordonMaker.threadStock = 12; StateCordonMaker.goldStock = 8; StateCordonMaker.silverStock = 6; StateCordonMaker.jewelStock = 4; StateCordonMaker.pearlStock = 4
StateCordonMaker.productStock = {}; StateCordonMaker.buildings = {}; StateCordonMaker.maker = nil; StateCordonMaker.activeMaking = {}; StateCordonMaker.totalProducts = 0; StateCordonMaker.dayTimer = 0
function StateCordonMaker.init() StateCordonMaker.silkStock=14; StateCordonMaker.threadStock=12; StateCordonMaker.goldStock=8; StateCordonMaker.silverStock=6; StateCordonMaker.jewelStock=4; StateCordonMaker.pearlStock=4; StateCordonMaker.productStock={}; StateCordonMaker.buildings={}; StateCordonMaker.maker=nil; StateCordonMaker.activeMaking={}; StateCordonMaker.totalProducts=0; StateCordonMaker.dayTimer=0; print("[StateCordonMaker] Royal State Cordon Maker System initialized (6 products, 4 buildings)") end
function StateCordonMaker.hireMaker(n,s) s=s or math.random(55,90); local c=560+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; StateCordonMaker.maker={name=n or ("Cordonar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Cordonar najet: %s (spretnost: %d)",StateCordonMaker.maker.name,s),"success") end; return true end
function StateCordonMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function StateCordonMaker.build(id) local ok,e=StateCordonMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(StateCordonMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function StateCordonMaker.getQualityBonus() local b=0; for _,bd in ipairs(StateCordonMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function StateCordonMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.silkCost and StateCordonMaker.silkStock<(d.silkCost or 0) then return false,"Premalo svile" end; if d.threadCost and StateCordonMaker.threadStock<(d.threadCost or 0) then return false,"Premalo niti" end; if d.goldCost and StateCordonMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.silverCost and StateCordonMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.jewelCost and StateCordonMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and StateCordonMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #StateCordonMaker.buildings==0 then return false,"Potrebna cordonska delavnica" end; if not StateCordonMaker.maker then return false,"Potreben cordonar" end; return true end
function StateCordonMaker.make(pt,qty) qty=qty or 1; local ok,e=StateCordonMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.silkCost then StateCordonMaker.silkStock=StateCordonMaker.silkStock-d.silkCost*qty end; if d.threadCost then StateCordonMaker.threadStock=StateCordonMaker.threadStock-d.threadCost*qty end; if d.goldCost then StateCordonMaker.goldStock=StateCordonMaker.goldStock-d.goldCost*qty end; if d.silverCost then StateCordonMaker.silverStock=StateCordonMaker.silverStock-d.silverCost*qty end; if d.jewelCost then StateCordonMaker.jewelStock=StateCordonMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then StateCordonMaker.pearlStock=StateCordonMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if StateCordonMaker.maker then t=math.max(1,t-math.floor(StateCordonMaker.maker.skill/13)) end; table.insert(StateCordonMaker.activeMaking,{id="statecordon_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Pletenje: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function StateCordonMaker.completeMaking(m) local q=1.0+(StateCordonMaker.getQualityBonus()/100); if StateCordonMaker.maker then q=q+(StateCordonMaker.maker.skill/140) end; q=math.min(2.5,q); StateCordonMaker.productStock[m.productType]=(StateCordonMaker.productStock[m.productType] or 0)+m.quantity; StateCordonMaker.totalProducts=StateCordonMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if StateCordonMaker.maker then StateCordonMaker.maker.itemsMade=StateCordonMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then StateCordonMaker.maker.skill=math.min(100,StateCordonMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Cordon izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"statecordon.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function StateCordonMaker.update(dt) if not _G.state then return end; StateCordonMaker.dayTimer=StateCordonMaker.dayTimer+dt; if StateCordonMaker.dayTimer>=30 then StateCordonMaker.dayTimer=0; for i=#StateCordonMaker.activeMaking,1,-1 do local m=StateCordonMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then StateCordonMaker.completeMaking(m); table.remove(StateCordonMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(StateCordonMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if StateCordonMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function StateCordonMaker.getStats() return {silkStock=StateCordonMaker.silkStock,threadStock=StateCordonMaker.threadStock,goldStock=StateCordonMaker.goldStock,silverStock=StateCordonMaker.silverStock,jewelStock=StateCordonMaker.jewelStock,pearlStock=StateCordonMaker.pearlStock,productStock=StateCordonMaker.productStock,numBuildings=#StateCordonMaker.buildings,hasMaker=StateCordonMaker.maker~=nil,makerName=StateCordonMaker.maker and StateCordonMaker.maker.name or "—",makerSkill=StateCordonMaker.maker and StateCordonMaker.maker.skill or 0,activeMaking=#StateCordonMaker.activeMaking,totalProducts=StateCordonMaker.totalProducts} end
return StateCordonMaker
